              <div className="mt-3 flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={() => {
                    if (alert.action.kind === "invoice") {
                      onOpenInvoice(alert.action.invoiceId);
                    } else {
                      onOpenForecast();
                    }
                  }}
                  className="rounded-md bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800"
                >
                  {alert.actionLabel}
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}


