// Synthetic data model for PS-01 (see PROJECT_SPEC.md section 6).
// All dates are ISO calendar dates "YYYY-MM-DD"; all money is INR as a number.

export type ClientType = "design" | "tutoring";

export interface Client {
  id: string;
  name: string;
  type: ClientType;
  city: string;
