  receivedDate: string;
}

export type BillStatus = "upcoming" | "paid" | "overdue";

export type Recurrence = "one-time" | "monthly" | "quarterly" | "yearly";

export interface Bill {
  id: string;
  name: string;
  category: string;
  amountINR: number;
