            <svg
              aria-hidden="true"
              viewBox="0 0 24 24"
              className="h-5 w-5"
              fill="none"
              stroke="currentColor"
              strokeWidth={2}
              strokeLinecap="round"
            >
              <path d="M4 7h16M4 12h16M4 17h16" />
            </svg>
          </button>
        </div>
        {menuOpen && (
          <nav
            id={MOBILE_MENU_ID}
            className="absolute inset-x-0 top-full flex flex-col gap-1 border-b border-slate-200 bg-white px-3 pb-3 shadow-sm"
