  results.push({ id, status, detail });
  console.log(`[${status}] ${id}: ${detail}`);
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const pad = (n) => String(n).padStart(2, '0');

function parseAmount(text) {
  const m = String(text).match(/(-)?\s*₹\s*([\d,]+(?:\.\d+)?)/) || String(text).match(/(-)?\s*(\d[\d,]*(?:\.\d+)?)/);
  if (!m) return null;
  const n = Number(m[2].replace(/,/g, ''));
  return m[1] ? -n : n;
}
// First amount on the line containing `label`, or on the next two lines.
function amountAfterLabel(bodyText, label) {
  const lines = bodyText.split('\n').map((l) => l.trim()).filter(Boolean);
  const idx = lines.findIndex((l) => l.toLowerCase().includes(label.toLowerCase()));
  if (idx < 0) return null;
  for (let i = idx; i <= Math.min(idx + 2, lines.length - 1); i++) {
    if (/₹|\d/.test(lines[i])) {
      const v = parseAmount(lines[i]);
      if (v !== null) return v;
    }
  }
  return null;
}
function toIso(text) {
  const iso = String(text).match(/\d{4}-\d{2}-\d{2}/);
  if (iso) return iso[0];
  const d = new Date(text);
  if (isNaN(d)) return null;
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}
// Monthly step from an anchor, keeping the anchor day and clamping to month end.
function addMonthsClamped(iso, n) {
  const [y, m, d] = iso.split('-').map(Number);
  const total = m - 1 + n;
  const ty = y + Math.floor(total / 12);
  const tm = ((total % 12) + 12) % 12;
  const dim = new Date(Date.UTC(ty, tm + 1, 0)).getUTCDate();
  return `${ty}-${pad(tm + 1)}-${pad(Math.min(d, dim))}`;
}

async function main() {
  const browser = await chromium.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: true,
  });
  const context = await browser.newContext({ viewport: DESKTOP });
  const page = await context.newPage();
