      await form.waitFor({ state: 'visible', timeout: 5000 });
    }
    return form;
  }
  async function fillForm(form, { name, category, amount, date, recurring }) {
    await form.getByLabel(/^title/i).fill(name);
    await form.getByLabel(/^category/i).fill(category);
    await form.getByLabel(/amount/i).fill(amount);
    await form.getByLabel(/due date/i).fill(date);
    const rec = form.getByLabel(/recurring/i);
    if (await rec.count()) (recurring ? await rec.check() : await rec.uncheck());
  }
  async function addBill(spec) {
    const form = await openAddForm();
    await fillForm(form, spec);
    await form.getByRole('button', { name: /add bill|save|create/i }).first().click();
    await sleep(400);
  }
  async function tryInvalid(amount) {
    const form = await openAddForm();
    await fillForm(form, { name: TEST_BAD, category: 'QA', amount, date: '2025-07-01', recurring: false });
    await form.getByRole('button', { name: /add bill|save|create/i }).first().click();
    await sleep(300);
    const stillOpen = await form.isVisible().catch(() => false);
    const badRows = await rowsNamed(TEST_BAD).count();
    const text = stillOpen ? await form.innerText() : '';
    const errLine = text.split('\n').find((l) => /positive|valid|enter|invalid|required|must/i.test(l)) || null;
    return { stillOpen, badRows, errLine };
  }
  async function forecastSnapshot() {
    await goTo('Cash Forecast');
    const t = await bodyText();
    const lines = t.split('\n').map((l) => l.trim()).filter((l) => /₹/.test(l) && !/confirmed/i.test(l));
    return { lines, confirmed: amountAfterLabel(t, 'Confirmed cash') };
  }
  async function controlSnapshot() {
    return page.evaluate(() => {
      const out = [];
      document.querySelectorAll('input, select, [role="tab"], [aria-pressed]').forEach((el) => {
        if (el.closest('aside')) return;
        const tag = el.tagName.toLowerCase();
        const type = el.getAttribute('type') || '';
        const label = el.getAttribute('aria-label') || (el.labels && el.labels[0] ? el.labels[0].innerText : '') || el.textContent.trim().slice(0, 40);
        let v;
        if (type === 'checkbox' || type === 'radio') v = el.checked;
        else if (tag === 'input' || tag === 'select') v = el.value;
        else v = el.getAttribute('aria-selected') ?? el.getAttribute('aria-pressed');
        out.push(`${tag}[${type}]|${label}|${v}`);
      });
      return out;
    });
  }

  // Steps appended below in the same file.
  // ... (see continuation)
  await browser.close();
}
main().catch((e) => { console.error('FATAL', e); process.exitCode = 1; });
