import { chromium } from 'file:///D:/ps01-back-office/node_modules/@playwright/test/index.mjs';
import fs from 'node:fs';
import path from 'node:path';

const BASE = 'http://localhost:5173/';
const ROOT = path.join(process.env.TEMP || 'C:/Temp', 'ps01-stage0');
const SHOTS = path.join(ROOT, 'screens');
const LOGS = path.join(ROOT, 'logs');
fs.mkdirSync(SHOTS, { recursive: true });
fs.mkdirSync(LOGS, { recursive: true });

const DESKTOP = { width: 1440, height: 900 };
const MOBILE = { width: 390, height: 844 };
const NAME_ONE = 'QA One-time Test';
const NAME_REC = 'QA Recurring Test';
const NAME_BAD = 'QA Invalid Test';
const DATE_ONE = '2026-12-10';
const DATE_REC = '2026-12-20';

const results = [];
const consoleLog = [];
const netLog = [];
const dialogs = [];

const report = (id, status, detail) => {
  results.push({ id, status, detail });
  console.log(`[${status}] ${id}: ${detail}`);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const pad = (n) => String(n).padStart(2, '0');
const json = (v) => JSON.stringify(v);

function num(s) {
  const m = String(s).match(/(?:₹|INR|Rs\.?)\s*(-?[\d,]+(?:\.\d+)?)/i);
  return m ? Number(m[1].replace(/,/g, '')) : null;
}
function linesOf(text) {
  return String(text).split('\n').map((l) => l.trim()).filter(Boolean);
}
function amountAfter(text, label) {
  const lines = linesOf(text);
  const i = lines.findIndex((l) => l.toLowerCase().includes(label.toLowerCase()));
  if (i < 0) return null;
  for (let j = i; j <= Math.min(i + 3, lines.length - 1); j++) {
    const v = num(lines[j]);
    if (v !== null) return v;
  }
  return null;
}
function accountBalance(text, id) {
  const lines = linesOf(text);
  const i = lines.findIndex((l) => l.includes(id));
  if (i < 0) return null;
  for (let j = i; j <= Math.min(i + 3, lines.length - 1); j++) {
    const v = num(lines[j].split(id).join(''));
    if (v !== null) return v;
  }
  return null;
}
function projectedNumbers(text) {
  return linesOf(text)
    .filter((l) => /projected|lowest|forecast|balance/i.test(l) && !/confirmed/i.test(l))
    .map((l) => num(l))
    .filter((v) => v !== null);
}
function toIso(text) {
  const iso = String(text).match(/\d{4}-\d{2}-\d{2}/);
  if (iso) return iso[0];
  const pats = [/\d{1,2}\s+[A-Za-z]{3,9}\s+\d{4}/, /[A-Za-z]{3,9}\s+\d{1,2},?\s+\d{4}/];
  for (const p of pats) {
    const m = String(text).match(p);
    if (m) {
      const d = new Date(m[0]);
      if (!isNaN(d)) return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    }
  }
  return null;
}
function addMonthsClamped(iso, n) {
  const [y, m, d] = iso.split('-').map(Number);
  const total = m - 1 + n;
  const ty = y + Math.floor(total / 12);
  const tm = ((total % 12) + 12) % 12;
  const dim = new Date(Date.UTC(ty, tm + 1, 0)).getUTCDate();
  return `${ty}-${pad(tm + 1)}-${pad(Math.min(d, dim))}`;
}

async function main() {
  const browser = await chromium.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: true,
  });
  const context = await browser.newContext({ viewport: DESKTOP });
  const page = await context.newPage();
  page.on('console', (m) => { if (m.type() === 'error') consoleLog.push(`console: ${m.text()}`); });
  page.on('pageerror', (e) => consoleLog.push(`pageerror: ${e.message}`));
  page.on('dialog', async (d) => { dialogs.push(d.message()); await d.accept(); });
  page.on('response', (r) => {
    if (r.status() >= 400) netLog.push(`HTTP ${r.status()} ${r.request().method()} ${r.url()} (page ${page.url()})`);
  });
  page.on('requestfailed', (r) => netLog.push(`FAILED ${r.url()} ${r.failure() ? r.failure().errorText : ''} (page ${page.url()})`));

  const state = { base: null, whatIfStart: null };

  const body = () => page.locator('body').innerText();
  const row = (name) => page.getByTestId('bill-row').filter({ hasText: name });
  const rowCount = (name) => row(name).count();
  const rowText = async (name) => (await row(name).first().innerText()).replace(/\s+/g, ' ');
  const allRows = () => page.getByTestId('bill-row').count();
  const payCtrls = (name) => row(name).first().getByRole('button', { name: /pay|mark/i });

  async function step(id, fn) {
    try { await fn(); } catch (e) { report(id, 'NOT VERIFIED', `exception: ${String(e.message).split('\n')[0]}`); }
  }

  async function nav(label) {
    const re = new RegExp('^\\s*' + label, 'i');
    let t = page.getByRole('button', { name: re }).first();
    if (!(await t.isVisible().catch(() => false))) t = page.getByRole('link', { name: re }).first();
    if (!(await t.isVisible().catch(() => false))) {
      const menu = page.getByRole('button', { name: /menu/i }).first();
      if (await menu.count()) { await menu.click(); await sleep(400); }
      t = page.getByRole('button', { name: re }).first();
      if (!(await t.isVisible().catch(() => false))) t = page.getByRole('link', { name: re }).first();
    }
    await t.click();
    await page.waitForLoadState('networkidle');
    await sleep(300);
  }

  async function openAdd() {
    const f = page.getByTestId('add-bill-form');
    if (!(await f.isVisible().catch(() => false))) {
      await page.getByRole('button', { name: /^\s*add bill\s*$/i }).first().click();
      await f.waitFor({ state: 'visible', timeout: 5000 });
    }
