          const classes = info.tables.map((t) => {
            if (t.scroller) return `table${t.i}: CONTAINED (scroller ${t.scroller.clientWidth}/${t.scroller.scrollWidth})`;
            if (t.right <= info.vw) return `table${t.i}: FITS (right ${t.right})`;
