    const sel = page.getByTestId('account-select').first();
    if (!(await sel.count())) return 'NOT FOUND';
    if ((await sel.inputValue()) !== 'CA-02') await sel.selectOption('CA-02');
    return sel.inputValue();
  }
  async function controlSnapshot() {
    return page.evaluate(() => {
      const scope = document.querySelector('main') || document.body;
      const out = [];
      scope.querySelectorAll('input, select, [role="tab"], [aria-pressed]').forEach((el) => {
        if (el.closest('aside')) return;
        const tag = el.tagName.toLowerCase();
        const type = el.getAttribute('type') || '';
        const label = el.getAttribute('aria-label') || (el.labels && el.labels[0] ? el.labels[0].innerText : '') || el.textContent.trim().slice(0, 40);
        let v;
        if (type === 'checkbox' || type === 'radio') v = el.checked;
        else if (tag === 'input' || tag === 'select') v = el.value;
        else v = el.getAttribute('aria-selected') ?? el.getAttribute('aria-pressed');
        out.push(`${tag}[${type}]|${label}|${v}`);
      });
      return out;
    });
  }

  async function captureRemaining(tag) {
    try {
      await nav('Bills');
      const t = await body();
      const remaining = {
        qaOneTimeRows: await rowCount(NAME_ONE),
        qaRecurringRows: await rowCount(NAME_REC),
        qaInvalidRows: await rowCount(NAME_BAD),
        billRows: await allRows(),
        confirmed: amountAfter(t, 'Confirmed cash'),
        ca02: accountBalance(t, 'CA-02'),
      };
      fs.writeFileSync(path.join(LOGS, `remaining-state-${tag}.json`), JSON.stringify(remaining, null, 2));
      await page.screenshot({ path: path.join(SHOTS, `remaining-state-${tag}.png`), fullPage: true });
      return remaining;
    } catch (e) {
      return { unreadable: String(e.message).split('\n')[0] };
    }
  }

  async function resetAndVerify(tag) {
    const id = `RESET (${tag})`;
    try {
      if (!state.base) {
        const rem = await captureRemaining(tag);
        report(id, 'FAIL', `reset cannot be verified: no baseline was captured. Remaining state: ${json(rem)}`);
        return false;
      }
      await nav('Bills');
      const btn = page.getByRole('button', { name: /reset demo data/i }).first();
      if (!(await btn.count())) {
        const rem = await captureRemaining(tag);
        report(id, 'FAIL', `Reset Demo Data button not found. Remaining state: ${json(rem)}`);
        return false;
      }
      const dialogsBefore = dialogs.length;
      await btn.click();
      await sleep(800);
      const confirmSeen = dialogs.slice(dialogsBefore).some((m) => /reset/i.test(m));
      await nav('Bills');
      const t = await body();
      const confirmed = amountAfter(t, 'Confirmed cash');
      const ca02 = accountBalance(t, 'CA-02');
      const rows = await allRows();
      const qaGone = (await rowCount(NAME_ONE)) === 0 && (await rowCount(NAME_REC)) === 0 && (await rowCount(NAME_BAD)) === 0;
      await nav('Cash Forecast');
      const wiAfter = await controlSnapshot();
      const wiOk = json(wiAfter) === json(state.whatIfStart);
      const balOk = confirmed === state.base.confirmed && ca02 === state.base.ca02;
      const rowsOk = rows === state.base.rows;
      const ok = confirmSeen && qaGone && balOk && rowsOk && wiOk;
      const detail = `confirmDialog=${confirmSeen}; QA rows gone=${qaGone}; Confirmed ${confirmed} (baseline ${state.base.confirmed}); CA-02 ${ca02} (baseline ${state.base.ca02}); billRows ${rows} (baseline ${state.base.rows}); What-If restored=${wiOk}`;
      await page.screenshot({ path: path.join(SHOTS, `reset-${tag}.png`), fullPage: true });
      if (ok) {
        report(id, 'PASS', detail);
        return true;
      }
      const rem = await captureRemaining(tag);
      report(id, 'FAIL', `${detail}. Remaining state: ${json(rem)}`);
      return false;
    } catch (e) {
      const rem = await captureRemaining(tag);
      report(id, 'FAIL', `reset could not be completed: ${String(e.message).split('\n')[0]}. Remaining state: ${json(rem)}`);
      return false;
    }
  }

  try {
    await page.goto(BASE, { waitUntil: 'networkidle' });
    await step('BASELINE', async () => {
      await nav('Bills');
      const t = await body();
      state.base = { confirmed: amountAfter(t, 'Confirmed cash'), ca02: accountBalance(t, 'CA-02'), rows: await allRows() };
      await page.screenshot({ path: path.join(SHOTS, 'bills-baseline.png'), fullPage: true });
      await nav('Cash Forecast');
      state.whatIfStart = await controlSnapshot();
      if (state.base.confirmed === null || state.base.ca02 === null) {
        throw new Error(`baseline values unreadable: ${json(state.base)}`);
      }
      report('BASELINE', 'PASS', `Confirmed=${state.base.confirmed} CA-02=${state.base.ca02} billRows=${state.base.rows} whatIfControls=${state.whatIfStart.length}`);
    });

    await step('C1 add valid one-time bill', async () => {
      await nav('Bills');
      const f = await openAdd();
      await fill(f, { name: NAME_ONE, category: 'QA', amount: '1000', date: DATE_ONE, recurring: false });
      await submit(f);
      const n = await rowCount(NAME_ONE);
      report('C1 add valid one-time bill', n === 1 ? 'PASS' : 'FAIL',
        `rows named "${NAME_ONE}": ${n}; row="${n ? await rowText(NAME_ONE) : '-'}"; rows total ${await allRows()} (baseline ${state.base.rows})`);
    });

    await step('C2 invalid amounts rejected', async () => {
      const obs = [];
      let allOk = true;
      for (const amt of ['0', '-5', '1.234', '12a', '1e3']) {
        const f = await openAdd();
        await fill(f, { name: NAME_BAD, category: 'QA', amount: amt, date: DATE_ONE, recurring: false });
        const typed = await f.getByLabel(/amount/i).inputValue();
        await submit(f);
        const open = await f.isVisible().catch(() => false);
        const bad = await rowCount(NAME_BAD);
        const errLines = open ? linesOf(await f.innerText()).filter((l) => /positive|valid|enter|must|required|invalid/i.test(l)) : [];
        const ok = open && bad === 0;
        allOk = allOk && ok;
        obs.push(`${amt}: input value="${typed}" formOpen=${open} badRows=${bad} errors=${json(errLines)}`);
      }
      report('C2 invalid amounts rejected', allOk ? 'PASS' : 'FAIL', obs.join(' | '));
    });

    let fcBefore = null;
    await step('C3 pre-payment forecast snapshot', async () => {
      await nav('Cash Forecast');
      const t = await body();
      fcBefore = { confirmed: amountAfter(t, 'Confirmed cash'), proj: projectedNumbers(t) };
      await nav('Bills');
    });

    await step('C3 pay one-time bill from CA-02', async () => {
      await nav('Bills');
      const selVal = await selectCA02();
      const before = await body();
      const caBefore = accountBalance(before, 'CA-02');
      const confBefore = amountAfter(before, 'Confirmed cash');
      const payersBefore = await payCtrls(NAME_ONE).count();
      await payCtrls(NAME_ONE).first().click();
      await sleep(400);
      const after = await body();
      const caAfter = accountBalance(after, 'CA-02');
      const confAfter = amountAfter(after, 'Confirmed cash');
      const rt = await rowText(NAME_ONE);
      const paid = /\bPaid\b/i.test(rt);
      const ctrls = payCtrls(NAME_ONE);
      const payersAfter = await ctrls.count();
      const enabledAfter = payersAfter ? await ctrls.evaluateAll((els) => els.filter((e) => !e.disabled).length) : 0;
      await nav('Cash Forecast');
      await nav('Bills');
      const caStable = accountBalance(await body(), 'CA-02');
      const auditHits = (after.match(new RegExp(NAME_ONE, 'g')) || []).length;
      const auditVisible = /payment (history|record|log)|audit|recent payments/i.test(after);
      await page.screenshot({ path: path.join(SHOTS, 'bills-after-pay.png'), fullPage: true });
      const ok = paid && enabledAfter === 0
        && caBefore !== null && caAfter !== null && caBefore - caAfter === 1000
        && caStable === caAfter
        && confBefore !== null && confAfter !== null && confBefore - confAfter === 1000;
      report('C3 pay one-time bill from CA-02', ok ? 'PASS' : 'FAIL',
        `selector=${selVal}; row="${rt}"; paid=${paid}; payControlsBefore=${payersBefore}; payControlsAfter=${payersAfter}; enabledAfter=${enabledAfter}; CA-02 ${caBefore}->${caAfter} (delta ${caBefore !== null && caAfter !== null ? caBefore - caAfter : 'n/a'}); CA-02 after re-navigation=${caStable}; Confirmed ${confBefore}->${confAfter}; audit section visible=${auditVisible}; name occurrences on page=${auditHits}`);
    });

    await step('C3 forecast after payment (no double count)', async () => {
      await nav('Cash Forecast');
      const t = await body();
      const confAfter = amountAfter(t, 'Confirmed cash');
      const proj = projectedNumbers(t);
      if (!fcBefore || proj.length === 0) {
        report('C3 forecast after payment', 'NOT VERIFIED', `projected figures not found; text sample: ${json(linesOf(t).slice(0, 12))}`);
        return;
      }
      const confOk = fcBefore.confirmed !== null && confAfter !== null && fcBefore.confirmed - confAfter === 1000;
      const projSame = json(fcBefore.proj) === json(proj);
      report('C3 forecast after payment', confOk && projSame ? 'PASS' : 'FAIL',
        `Confirmed on forecast ${fcBefore.confirmed}->${confAfter} (delta 1000 expected); projected before=${json(fcBefore.proj)} after=${json(proj)}`);
      await page.screenshot({ path: path.join(SHOTS, 'cash-forecast-after-pay.png'), fullPage: true });
    });

    await step('C4 recurring bill: add, pay one occurrence, advance due date', async () => {
      await nav('Bills');
      const f = await openAdd();
      await fill(f, { name: NAME_REC, category: 'QA', amount: '500', date: DATE_REC, recurring: true });
      await submit(f);
      if ((await rowCount(NAME_REC)) !== 1) {
        report('C4 recurring bill: add', 'FAIL', 'row not created');
        return;
      }
      const dueBefore = toIso(await rowText(NAME_REC));
      const caBefore = accountBalance(await body(), 'CA-02');
      await selectCA02();
      await payCtrls(NAME_REC).first().click();
      await sleep(400);
      const rtAfter = await rowText(NAME_REC);
      const dueAfter = toIso(rtAfter);
      const expected = dueBefore ? addMonthsClamped(dueBefore, 1) : null;
      const caAfter = accountBalance(await body(), 'CA-02');
      const ok = dueBefore !== null && dueAfter === expected && caBefore !== null && caAfter !== null && caBefore - caAfter === 500;
      report('C4 recurring bill: pay one occurrence', ok ? 'PASS' : 'FAIL',
        `displayed due before=${dueBefore} after=${dueAfter}; expected=${expected}; CA-02 ${caBefore}->${caAfter}; row after="${rtAfter}"`);
      await page.screenshot({ path: path.join(SHOTS, 'bills-after-recurring.png'), fullPage: true });
    });

    await step('C5 change What-If state', async () => {
      await nav('Cash Forecast');
      const tab = page.getByRole('button', { name: /^\s*60/ }).first();
      if (await tab.count()) await tab.click().catch(() => {});
      const range = page.locator('main input[type="range"]').first();
      if (await range.count()) {
        await range.evaluate((e) => {
          e.value = e.max;
          e.dispatchEvent(new Event('input', { bubbles: true }));
          e.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }
      const sel = page.locator('main select').first();
      if (await sel.count() && (await sel.locator('option').count()) > 1) await sel.selectOption({ index: 1 });
      await sleep(300);
      const changed = await controlSnapshot();
      report('C5 change What-If state', json(changed) !== json(state.whatIfStart || []) ? 'PASS' : 'NOT VERIFIED',
        `start=${json(state.whatIfStart)} changed=${json(changed)}`);
    });

    await step('C6 overflow at 390', async () => {
      await page.setViewportSize(MOBILE);
      for (const screen of ['Overview', 'Invoices', 'Cash Forecast']) {
        await step(`C6 overflow ${screen} @390`, async () => {
          await nav(screen);
          const info = await page.evaluate(() => {
            const vw = window.innerWidth;
            return {
              vw,
              docScrollWidth: document.documentElement.scrollWidth,
              tables: [...document.querySelectorAll('table')].map((t, i) => {
                let anc = t.parentElement;
                let scroller = null;
                while (anc && anc !== document.body) {
                  const cs = getComputedStyle(anc);
                  if (/(auto|scroll)/.test(cs.overflowX) && anc.scrollWidth > anc.clientWidth) {
                    scroller = { clientWidth: anc.clientWidth, scrollWidth: anc.scrollWidth };
                    break;
                  }
                  anc = anc.parentElement;
                }
                const r = t.getBoundingClientRect();
                return { i, right: Math.round(r.right), scroller };
              }),
            };
          });
          await page.screenshot({ path: path.join(SHOTS, `${screen.toLowerCase().replace(/ /g, '-')}-390.png`), fullPage: true });
          if (info.tables.length === 0) {
            report(`C6 overflow ${screen} @390`, 'NOT VERIFIED', `no <table> elements; docScrollWidth=${info.docScrollWidth}`);
            return;
          }
          const classes = info.tables.map((t) => {
            if (t.scroller) return `table${t.i}: CONTAINED (scroller ${t.scroller.clientWidth}/${t.scroller.scrollWidth})`;
            if (t.right <= info.vw) return `table${t.i}: FITS (right ${t.right})`;
            return `table${t.i}: OVERFLOWING (right ${t.right}, no scroller)`;
          });
          const bad = info.tables.some((t) => !t.scroller && t.right > info.vw);
          report(`C6 overflow ${screen} @390`, !bad && info.docScrollWidth <= info.vw ? 'PASS' : 'FAIL',
            `viewport=${info.vw} docScrollWidth=${info.docScrollWidth}; ${classes.join('; ')}`);
        });
      }
    });
  } finally {
    await page.setViewportSize(DESKTOP).catch(() => {});
    await resetAndVerify('cleanup');
  }

  await step('C7 Overview 404 URL', async () => {
    netLog.length = 0;
    await page.goto(BASE, { waitUntil: 'networkidle' });
    await sleep(800);
    const fails = netLog.filter((l) => /HTTP 404|FAILED/.test(l));
    report('C7 Overview 404 URL', fails.length ? 'FAIL' : 'PASS',
      fails.length ? fails.join(' | ') : 'no 404 or failed request on Overview load');
  });

  fs.writeFileSync(path.join(LOGS, 'results.json'), JSON.stringify(results, null, 2));
  fs.writeFileSync(path.join(LOGS, 'errors.txt'),
    ['== console/page errors ==', ...consoleLog, '== dialogs ==', ...dialogs, '== network 4xx/failed ==', ...netLog].join('\n'));
  console.log('\nSUMMARY');
  for (const r of results) console.log(`${r.status.padEnd(14)} ${r.id}`);
  await browser.close();
  process.exitCode = results.some((r) => r.status === 'FAIL' || r.status === 'NOT VERIFIED') ? 1 : 0;
}

main().catch((e) => { console.error('FATAL', e); process.exitCode = 1; });

